const size = 20

function Mark({ viewBox, className = '', children }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      xmlns="http://www.w3.org/2000/svg"
      className={`h-5 w-5 shrink-0 ${className}`}
      aria-hidden="true"
    >
      {children}
    </svg>
  )
}

function Raster({ src, invert, className = '' }) {
  return (
    <img
      src={src}
      alt=""
      width={size}
      height={size}
      className={`h-5 w-5 shrink-0 object-cover ${className} ${invert ? 'dark:invert' : ''}`}
      draggable={false}
    />
  )
}

